import json
from copy import deepcopy

def solve():
    # Define categories and values
    categories = {
        "Name": ["Eric", "Arnold", "Peter"],
        "Vacation": ["mountain", "city", "beach"],
        "Height": ["very short", "average", "short"],
        "Flower": ["carnations", "daffodils", "lilies"],
        "Hair": ["brown", "black", "blonde"],
        "Education": ["associate", "bachelor", "high school"],
    }

    houses = {1, 2, 3}

    def var(cat, val):
        return f"{cat}:{val}"

    # Initialize variables (each value maps to a house number)
    variables = {}
    for cat, vals in categories.items():
        for v in vals:
            variables[var(cat, v)] = set(houses)

    # Constraints
    equal_pairs = set()
    greater_pairs = set()
    equal_const = {}
    not_equal_const = {}

    # 1. Peter is the person who has an average height.
    equal_pairs.add((var("Name", "Peter"), var("Height", "average")))
    # 2. The person who loves a bouquet of daffodils is Arnold.
    equal_pairs.add((var("Flower", "daffodils"), var("Name", "Arnold")))
    # 3. The person who is very short is not in the second house.
    not_equal_const[var("Height", "very short")] = 2
    # 4. The person who loves beach vacations is in the first house.
    equal_const[var("Vacation", "beach")] = 1
    # 5. The person with a high school diploma is in the third house.
    equal_const[var("Education", "high school")] = 3
    # 6. The person who is short is somewhere to the right of the person who is very short.
    greater_pairs.add((var("Height", "short"), var("Height", "very short")))
    # 7. The person who loves the boquet of lilies is Eric.
    equal_pairs.add((var("Flower", "lilies"), var("Name", "Eric")))
    # 8. The person who loves the boquet of lilies is the person with a bachelor's degree.
    equal_pairs.add((var("Flower", "lilies"), var("Education", "bachelor")))
    # 9. The person who prefers city breaks is somewhere to the right of Peter.
    greater_pairs.add((var("Vacation", "city"), var("Name", "Peter")))
    # 10. The person who has blonde hair is in the third house.
    equal_const[var("Hair", "blonde")] = 3
    # 11. The person who loves beach vacations is the person who has brown hair.
    equal_pairs.add((var("Vacation", "beach"), var("Hair", "brown")))

    # All-different groups by category
    groups = []
    for cat, vals in categories.items():
        groups.append([var(cat, v) for v in vals])

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # Apply equal to constant
            for v, c in equal_const.items():
                if c not in domains[v]:
                    if len(domains[v]) == 0:
                        return None
                    # Contradiction handled below
                new_dom = domains[v].intersection({c})
                if len(new_dom) == 0:
                    return None
                if new_dom != domains[v]:
                    domains[v] = new_dom
                    changed = True

            # Apply not equal to constant
            for v, c in not_equal_const.items():
                if c in domains[v]:
                    if len(domains[v]) == 1 and c in domains[v]:
                        return None
                    new_dom = set(h for h in domains[v] if h != c)
                    if len(new_dom) == 0:
                        return None
                    if new_dom != domains[v]:
                        domains[v] = new_dom
                        changed = True

            # Apply equal pairs
            for a, b in equal_pairs:
                inter = domains[a].intersection(domains[b])
                if len(inter) == 0:
                    return None
                if inter != domains[a]:
                    domains[a] = inter
                    changed = True
                if inter != domains[b]:
                    domains[b] = inter
                    changed = True

            # Apply greater-than constraints: a > b
            for a, b in greater_pairs:
                dom_a = domains[a]
                dom_b = domains[b]
                # Allowed for a: there exists k in dom_b with h > k
                allowed_a = set()
                for h in dom_a:
                    if any(h > k for k in dom_b):
                        allowed_a.add(h)
                if len(allowed_a) == 0:
                    return None
                if allowed_a != dom_a:
                    domains[a] = allowed_a
                    changed = True

                # Allowed for b: there exists h in dom_a with h > k
                allowed_b = set()
                for k in dom_b:
                    if any(h > k for h in domains[a]):
                        allowed_b.add(k)
                if len(allowed_b) == 0:
                    return None
                if allowed_b != dom_b:
                    domains[b] = allowed_b
                    changed = True

            # Enforce all-different in each category
            for group in groups:
                # Collect assigned houses
                assigned_houses = set()
                for v in group:
                    if len(domains[v]) == 1:
                        assigned_houses.update(domains[v])
                # Remove assigned houses from other variables in group
                for v in group:
                    if len(domains[v]) > 1:
                        new_dom = domains[v] - assigned_houses
                        if len(new_dom) == 0:
                            return None
                        if new_dom != domains[v]:
                            domains[v] = new_dom
                            changed = True

        return domains

    def is_complete(domains):
        return all(len(dom) == 1 for dom in domains.values())

    def select_unassigned_variable(domains):
        # Choose variable with smallest domain > 1
        unassigned = [v for v, d in domains.items() if len(d) > 1]
        if not unassigned:
            return None
        return min(unassigned, key=lambda v: len(domains[v]))

    def backtrack(domains):
        domains = propagate(deepcopy(domains))
        if domains is None:
            return None
        if is_complete(domains):
            return domains

        var_to_assign = select_unassigned_variable(domains)
        for value in sorted(domains[var_to_assign]):
            new_domains = deepcopy(domains)
            new_domains[var_to_assign] = {value}
            result = backtrack(new_domains)
            if result is not None:
                return result
        return None

    solution_domains = backtrack(variables)
    if solution_domains is None:
        raise ValueError("No solution found")

    # Build output rows
    header = ["House", "Name", "Vacation", "Height", "Flower", "Hair", "Education"]
    rows = []
    for h in sorted(houses):
        row = [str(h)]
        for cat in header[1:]:
            vals = categories[cat]
            # Find which value in this category has house h
            chosen = None
            for v in vals:
                if next(iter(solution_domains[var(cat, v)])) == h:
                    chosen = v
                    break
            row.append(chosen)
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
